use serde::{Deserialize, Serialize};
use std::collections::HashMap;

pub (crate) trait Pack < C : cfg :: Config > : Sized { # [doc = " The number of bits occupied by this type when packed into a usize."] # [doc = ""] # [doc = " This must be provided to determine the number of bits into which to pack"] # [doc = " the type."] const LEN : usize ; # [doc = " The type packed on the less significant side of this type."] # [doc = ""] # [doc = " If this type is packed into the least significant bit of a usize, this"] # [doc = " should be `()`, which occupies no bytes."] # [doc = ""] # [doc = " This is used to calculate the shift amount for packing this value."] type Prev : Pack < C > ; # [doc = " A number consisting of `Self::LEN` 1 bits, starting at the least"] # [doc = " significant bit."] # [doc = ""] # [doc = " This is the higest value this type can represent. This number is shifted"] # [doc = " left by `Self::SHIFT` bits to calculate this type's `MASK`."] # [doc = ""] # [doc = " This is computed automatically based on `Self::LEN`."] const BITS : usize = { let shift = 1 << (Self :: LEN - 1) ; shift | (shift - 1) } ; # [doc = " The number of bits to shift a number to pack it into a usize with other"] # [doc = " values."] # [doc = ""] # [doc = " This is caculated automatically based on the `LEN` and `SHIFT` constants"] # [doc = " of the previous value."] const SHIFT : usize = Self :: Prev :: SHIFT + Self :: Prev :: LEN ; # [doc = " The mask to extract only this type from a packed `usize`."] # [doc = ""] # [doc = " This is calculated by shifting `Self::BITS` left by `Self::SHIFT`."] const MASK : usize = Self :: BITS << Self :: SHIFT ; fn as_usize (& self) -> usize ; fn from_usize (val : usize) -> Self ; # [inline (always)] fn pack (& self , to : usize) -> usize { let value = self . as_usize () ; debug_assert ! (value <= Self :: BITS) ; (to & ! Self :: MASK) | (value << Self :: SHIFT) } # [inline (always)] fn from_packed (from : usize) -> Self { let value = (from & Self :: MASK) >> Self :: SHIFT ; debug_assert ! (value <= Self :: BITS) ; Self :: from_usize (value) } }